def evaluate(current_reputation, observation, my_history, round_num):
    # Image scoring: reward donating to good recipients, punish defecting against good.
    # Use a simple heuristic: if donor donates to a recipient of high reputation, good;
    # if donor defects against a high reputation recipient, bad.
    # We don't have recipient's reputation in evaluate, so we approximate using current_reputation of donor?
    # Actually observation only gives donor and recipient IDs, not their reputations.
    # We can use current_reputation as the donor's current reputation (given by system).
    # But that's not the recipient's. The problem says evaluate receives "current_reputation" (of the observed agent).
    # So we only have the donor's current reputation, not the recipient's.
    # We need to assess based on the donor's action and the context. Since we don't have recipient reputation,
    # we can use a simpler approach: just update based on action alone.
    # To create diversity, we'll define a strategy that uses a different update magnitude.
    # Let's use a small update for donations and large for defections.
    if observation["action"] == "donate":
        return min(1.0, current_reputation + 0.2)
    else:
        return max(-1.0, current_reputation - 0.5)

def decide(recipient_reputation, round_num, my_history):
    # Donate only if recipient reputation is high.
    return recipient_reputation > 0.5

